3	namespace App\Http\Controllers\Api\PublicSite;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\DetectsClientInfo;
7	use App\Http\Controllers\Concerns\HashesClientData;
8	use App\Http\Controllers\Concerns\ResolvesSiteFromRequest;
9	use App\Http\Requests\Api\PublicSite\Analytics\CartEventRequest;
10	use App\Http\Requests\Api\PublicSite\Analytics\ClickRequest;
11	use App\Http\Requests\Api\PublicSite\Analytics\PageviewRequest;
12	use App\Jobs\Analytics\RebuildSiteHourlyAggregatesJob;
13	use App\Models\Analytics\CartEvent;
14	use App\Models\Analytics\LinkClick;
15	use App\Models\Analytics\SiteVisit;
16	use App\Models\Core\Site\Block;
17	use App\Services\Cache\AnalyticsCacheService;
18	use Illuminate\Http\JsonResponse;
19	use Throwable;
20	
21	// V2: Records pageview and click analytics events from public mini-sites. Events feed into hourly/daily aggregate jobs.
22	class AnalyticsController extends ApiController
23	{
24	    use DetectsClientInfo;
25	    use HashesClientData;
26	    use ResolvesSiteFromRequest;
27	
28	    public function __construct(
29	        private AnalyticsCacheService $analyticsCache
30	    ) {}
31	
32	    public function pageview(PageviewRequest $request): JsonResponse
33	    {
34	        $data = $request->validated();
35	
36	        // Resolve site by ID or subdomain
37	        $site = $this->resolveSiteFromData($data);
38	
39	        if (! $site) {
40	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
41	            // 404 when only a subdomain was given and simply wasn't found.
42	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
43	
44	            return $this->error('Site not found', $statusCode);
45	        }
46	
47	        // 404 not 403: public endpoint — returning 403 would reveal the site exists but is unpublished
48	        if (! $site->is_published) {
49	            return $this->error('Site not found', 404);
50	        }
51	
52	        // Create pageview record
53	        $visit = new SiteVisit([
54	            'occurred_at' => now(),
55	            'session_id' => $data['session_id'] ?? null,
56	            'visitor_id' => $data['visitor_id'] ?? null,
57	            'ip_hash' => $this->hashIp($request->ip()),
58	            'user_agent' => $request->userAgent(),
59	            'referrer' => $data['referrer'] ?? $request->headers->get('referer'),
60	            'utm_source' => $data['utm_source'] ?? null,
61	            'utm_medium' => $data['utm_medium'] ?? null,
62	            'utm_campaign' => $data['utm_campaign'] ?? null,
63	            'country_code' => $this->detectCountryCode($request),
64	            'device_type' => $this->detectDeviceType($request->userAgent()),
65	        ]);
66	        $visit->professional_id = $site->professional_id;
67	        $visit->site_id = $site->id;
68	        $visit->save();
69	
70	        RebuildSiteHourlyAggregatesJob::dispatch(
71	            (string) $site->professional_id,
72	            $visit->occurred_at?->copy()->utc()->startOfHour()->toIso8601String() ?? now()->utc()->startOfHour()->toIso8601String()
73	        );
74	
75	        try {
76	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
77	        } catch (Throwable) {
78	        }
79	
80	        return $this->success([
81	            'message' => 'Pageview recorded',
82	            'visit_id' => $visit->id,
83	        ], 201);
84	    }
85	
86	    public function click(ClickRequest $request): JsonResponse
87	    {
88	        $data = $request->validated();
89	
90	        // Resolve site by ID or subdomain
91	        $site = $this->resolveSiteFromData($data);
92	
93	        if (! $site) {
94	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
95	            // 404 when only a subdomain was given and simply wasn't found.
96	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
97	
98	            return $this->error('Site not found', $statusCode);
99	        }
100	
101	        // 404 not 403: public endpoint — returning 403 would reveal the site exists but is unpublished
102	        if (! $site->is_published) {
103	            return $this->error('Site not found', 404);
104	        }
105	
106	        // Verify block exists and belongs to this site
107	        $block = Block::where('id', $data['block_id'])
108	            ->where('site_id', $site->id)
109	            ->first();
110	
111	        if (! $block) {
112	            return $this->error('Block not found or does not belong to this site', 404);
113	        }
114	
115	        $blockGroup = strtolower((string) $block->block_group);
116	        $blockType = strtolower((string) $block->block_type);
117	        $trackableSectionTypes = collect(config('sidest.section_block_types', [
118	            'gallery',
119	            'services',
120	            'shop',
121	            'booking',
122	        ]))
123	            ->filter(fn ($type) => is_string($type) && trim($type) !== '')
124	            ->map(fn (string $type) => strtolower(trim($type)))
125	            ->values()
126	            ->all();
127	        $isTrackableLink = $blockGroup === 'links' && $blockType === 'link';
128	        $isTrackableSection =
129	            $blockGroup === 'sections'
130	            && in_array($blockType, $trackableSectionTypes, true);
131	
132	        if (! $isTrackableLink && ! $isTrackableSection) {
133	            return $this->error('Block is not trackable for analytics', 422);
134	        }
135	
136	        // 404 not 403: state check on a public endpoint — 403 reveals the block exists but is disabled
137	        if (! $block->is_active) {
138	            return $this->error('Block not found', 404);
139	        }
140	
141	        $click = LinkClick::runForBlockForeignKey(
142	            function (string $blockColumn) use ($request, $data, $site, $block) {
143	                // Dedup: return existing click if same visitor/session hit this block within 3 seconds.
144	                $hasIdentifier = ! empty($data['visitor_id']) || ! empty($data['session_id']);
145	                if ($hasIdentifier) {
146	                    $duplicate = LinkClick::where($blockColumn, $block->id)
147	                        ->where(function ($q) use ($data) {
148	                            if (! empty($data['visitor_id'])) {
149	                                $q->orWhere('visitor_id', $data['visitor_id']);
150	                            }
151	                            if (! empty($data['session_id'])) {
152	                                $q->orWhere('session_id', $data['session_id']);
153	                            }
154	                        })
155	                        ->where('occurred_at', '>=', now()->subSeconds(3))
156	                        ->first();
157	
158	                    if ($duplicate) {
159	                        return $duplicate;
160	                    }
161	                }
162	
163	                $click = new LinkClick([
164	                    'occurred_at' => now(),
165	                    'session_id' => $data['session_id'] ?? null,
166	                    'visitor_id' => $data['visitor_id'] ?? null,
167	                    'ip_hash' => $this->hashIp($request->ip()),
168	                    'user_agent' => $request->userAgent(),
169	                    'referrer' => $data['referrer'] ?? $request->headers->get('referer'),
170	                    'utm_source' => $data['utm_source'] ?? null,
171	                    'utm_medium' => $data['utm_medium'] ?? null,
172	                    'utm_campaign' => $data['utm_campaign'] ?? null,
173	                ]);
174	                $click->professional_id = $site->professional_id;
175	                $click->site_id = $site->id;
176	                $click->setAttribute($blockColumn, $block->id);
177	                $click->save();
178	
179	                return $click;
180	            }
181	        );
182	
183	        if (! $click instanceof LinkClick) {
184	            return $this->error('Unable to record click due to schema mismatch', 500);
185	        }
186	
187	        RebuildSiteHourlyAggregatesJob::dispatch(
188	            (string) $site->professional_id,
189	            $click->occurred_at?->copy()->utc()->startOfHour()->toIso8601String() ?? now()->utc()->startOfHour()->toIso8601String()
190	        );
191	
192	        try {
193	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
194	        } catch (Throwable) {
195	        }
196	
197	        return $this->success([
198	            'message' => $isTrackableSection ? 'Section interaction recorded' : 'Click recorded',
199	            'click_id' => $click->id,
200	        ], 201);
201	    }
202	
203	    public function cartEvent(CartEventRequest $request): JsonResponse
204	    {
205	        $data = $request->validated();
206	
207	        $site = $this->resolveSiteFromData($data);
208	
209	        if (! $site) {
210	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
211	
212	            return $this->error('Site not found', $statusCode);
213	        }
214	
215	        // 404 not 403: public endpoint — returning 403 would reveal the site exists but is unpublished
216	        if (! $site->is_published) {
217	            return $this->error('Site not found', 404);
218	        }
219	
220	        $event = new CartEvent([
221	            'event_type' => $data['event_type'],
222	            'occurred_at' => now(),
223	            'session_id' => $data['session_id'] ?? null,
224	            'visitor_id' => $data['visitor_id'] ?? null,
225	            'ip_hash' => $this->hashIp($request->ip()),
226	            'shopify_product_id' => $data['shopify_product_id'] ?? null,
227	            'quantity' => $data['quantity'] ?? null,
228	        ]);
229	        $event->professional_id = $site->professional_id;
230	        $event->site_id = $site->id;
231	        $event->save();
232	
233	        try {
234	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
235	        } catch (Throwable) {
236	        }
237	
238	        return $this->success(['message' => 'Cart event recorded', 'event_id' => $event->id], 201);
239	    }
240	}
