80	        // Handle API exceptions with JSON responses
81	        $exceptions->render(function (Throwable $e, Request $request) {
82	            // Only handle API routes
83	            if (! $request->is('api/*')) {
84	                return null;
85	            }
86	
87	            $response = null;
88	
89	            // Validation errors (422)
90	            if ($e instanceof ValidationException) {
91	                $response = response()->json([
92	                    'message' => 'Validation failed',
93	                    'errors' => $e->errors(),
94	                ], 422);
95	            }
96	
97	            // Model not found (404)
98	            elseif ($e instanceof ModelNotFoundException) {
99	                $response = response()->json([
100	                    'message' => 'Resource not found',
101	                ], 404);
102	            }
103	
104	            // Route not found (404)
105	            elseif ($e instanceof NotFoundHttpException) {
106	                $response = response()->json([
107	                    'message' => 'Endpoint not found',
108	                ], 404);
109	            }
110	
111	            // Policy denials via prepareException() — AuthorizationException(hasStatus=true)
112	            // becomes HttpException(status). denyAsNotFound() → HttpException(404), distinct
113	            // from NotFoundHttpException (route not found). denyWithStatus(423) → HttpException(423).
114	            elseif ($e instanceof HttpException
115	                && ! $e instanceof NotFoundHttpException
116	                && ($e->getStatusCode() === 404 || $e->getStatusCode() === 423)
117	            ) {
118	                $response = $e->getStatusCode() === 404
119	                    ? response()->json(['message' => 'Resource not found'], 404)
120	                    : response()->json(['message' => $e->getMessage() ?: 'Account is pending deletion.'], 423);
121	            }
122	
123	            // Forbidden (403)
124	            elseif ($e instanceof AccessDeniedHttpException) {
125	                \Illuminate\Support\Facades\Log::warning('Access denied', [
126	                    'path' => $request->path(),
127	                    'message' => $e->getMessage(),
128	                ]);
129	
130	                $response = response()->json([
131	                    'message' => $e->getMessage() ?: 'Access denied',
132	                ], 403);
133	            }
134	
135	            // Preserve explicit response exceptions (e.g. throttle 429)
136	            elseif ($e instanceof HttpResponseException) {
137	                $response = $e->getResponse();
138	            }
139	
140	            // Generic error handling
141	            else {
142	                $statusCode = 500;
143	                if ($e instanceof HttpException) {
144	                    $statusCode = $e->getStatusCode();
145	                }
146	
147	                // Log full exception for debugging even in production
148	                if ($statusCode >= 500) {
149	                    \Illuminate\Support\Facades\Log::error('API Error', [
150	                        'exception' => $e,
151	                        'status' => $statusCode,
152	                    ]);
153	                }
154	
155	                // Don't expose internal errors in production
156	                $message = config('app.debug')
157	                    ? $e->getMessage()
158	                    : 'An error occurred';
159	
160	                $response = response()->json([
161	                    'message' => $message,
162	                ], $statusCode);
163	            }
164	
165	            // Ensure CORS headers are present on all API error responses.
166	            // HandleCors middleware adds these during normal flow, but when
167	            // an exception propagates past it the rendered response skips
168	            // the CORS header injection. Laravel Cloud's proxy also strips
169	            // CORS headers on some error responses. This guard ensures the
170	            // browser can always read the error body.
171	            if ($response !== null
172	                && ! $response->headers->has('Access-Control-Allow-Origin')
173	            ) {
174	                $response->headers->set('Access-Control-Allow-Origin', '*');
175	            }
176	
177	            return $response;
178	        });
179	    })->create();
