3	namespace App\Http\Controllers\Concerns;
4	
5	use Illuminate\Http\Request;
6	
7	// V2: Detects client country code from CDN headers (Cloudflare, CloudFront, Vercel) and device type from user agent strings.
8	trait DetectsClientInfo
9	{
10	    /**
11	     * Detect country code from CDN headers (Cloudflare, CloudFront, Vercel).
12	     */
13	    protected function detectCountryCode(Request $request): ?string
14	    {
15	        $code =
16	            $request->header('CF-IPCountry') // Cloudflare
17	            ?? $request->header('CloudFront-Viewer-Country') // AWS CloudFront
18	            ?? $request->header('X-Vercel-IP-Country'); // Vercel
19	
20	        if (! is_string($code)) {
21	            return null;
22	        }
23	
24	        $code = strtoupper(trim($code));
25	
26	        if (! preg_match('/^[A-Z]{2}$/', $code)) {
27	            return null;
28	        }
29	
30	        return $code;
31	    }
32	
33	    /**
34	     * Detect devices type from user agent.
35	     */
36	    protected function detectDeviceType(?string $ua): ?string
37	    {
38	        if (! $ua) {
39	            return null;
40	        }
41	
42	        $u = strtolower($ua);
43	
44	        // Bots
45	        if (str_contains($u, 'bot') || str_contains($u, 'spider') || str_contains($u, 'crawler')) {
46	            return 'bot';
47	        }
48	
49	        // Tablet
50	        if (str_contains($u, 'ipad') || str_contains($u, 'tablet')) {
51	            return 'tablet';
52	        }
53	
54	        // Mobile
55	        if (str_contains($u, 'mobi') || str_contains($u, 'iphone') || str_contains($u, 'android')) {
56	            return 'mobile';
57	        }
58	
59	        return 'desktop';
60	    }
61	}
