148	                            if (! empty($data['visitor_id'])) {
149	                                $q->orWhere('visitor_id', $data['visitor_id']);
150	                            }
151	                            if (! empty($data['session_id'])) {
152	                                $q->orWhere('session_id', $data['session_id']);
153	                            }
154	                        })
155	                        ->where('occurred_at', '>=', now()->subSeconds(3))
156	                        ->first();
157	
158	                    if ($duplicate) {
159	                        return $duplicate;
160	                    }
161	                }
162	
163	                $click = new LinkClick([
164	                    'occurred_at' => now(),
165	                    'session_id' => $data['session_id'] ?? null,
166	                    'visitor_id' => $data['visitor_id'] ?? null,
167	                    'ip_hash' => $this->hashIp($request->ip()),
