13	
14	// V2: Records clicks on link blocks within a site. Handles block_id/link_block_id column migration gracefully with runtime column resolution.
15	class LinkClick extends BaseModel
16	{
17	    use HasUuids;
18	
19	    private static bool $blockForeignKeyResolved = false;
20	
21	    private static ?string $blockForeignKeyColumn = null;
22	
23	    protected $table = 'analytics.link_clicks';
24	
25	    public $incrementing = false;
26	
27	    protected $keyType = 'string';
28	
29	    // analytics tables don't have updated_at
30	    public $timestamps = false;
31	
32	    protected $fillable = [
33	        'occurred_at',
34	        'session_id',
35	        'visitor_id',
36	        'ip_hash',
37	        'user_agent',
38	        'referrer',
39	        'utm_source',
40	        'utm_medium',
41	        'utm_campaign',
42	    ];
43	
44	    protected $casts = [
45	        'occurred_at' => 'datetime',
46	        'created_at' => 'datetime',
47	    ];
48	
49	    public static function resolveBlockForeignKeyColumn(): ?string
50	    {
51	        if (self::$blockForeignKeyResolved) {
52	            return self::$blockForeignKeyColumn;
53	        }
54	
55	        self::$blockForeignKeyResolved = true;
56	
57	        try {
58	            $columns = DB::table('information_schema.columns')
59	                ->where('table_schema', 'analytics')
60	                ->where('table_name', 'link_clicks')
61	                ->whereIn('column_name', ['block_id', 'link_block_id'])
62	                ->pluck('column_name')
63	                ->all();
64	        } catch (\Throwable) {
65	            $columns = [];
66	        }
67	
68	        if (in_array('block_id', $columns, true)) {
69	            self::$blockForeignKeyColumn = 'block_id';
70	
71	            return self::$blockForeignKeyColumn;
72	        }
73	
74	        if (in_array('link_block_id', $columns, true)) {
75	            self::$blockForeignKeyColumn = 'link_block_id';
76	
77	            return self::$blockForeignKeyColumn;
78	        }
79	
80	        self::$blockForeignKeyColumn = null;
81	
82	        return null;
83	    }
84	
85	    public static function blockForeignKeyCandidates(): array
86	    {
87	        $resolved = self::resolveBlockForeignKeyColumn();
88	
89	        if ($resolved === 'block_id') {
90	            return ['block_id', 'link_block_id'];
91	        }
92	
93	        if ($resolved === 'link_block_id') {
94	            return ['link_block_id', 'block_id'];
95	        }
96	
97	        return ['block_id', 'link_block_id'];
98	    }
99	
100	    public static function runForBlockForeignKey(callable $callback, mixed $default = null): mixed
101	    {
102	        foreach (self::blockForeignKeyCandidates() as $column) {
103	            try {
104	                $result = $callback($column);
105	
106	                self::$blockForeignKeyResolved = true;
107	                self::$blockForeignKeyColumn = $column;
108	
109	                return $result;
110	            } catch (QueryException $e) {
111	                if (! self::isUndefinedColumnException($e)) {
112	                    throw $e;
113	                }
114	            }
115	        }
116	
117	        return $default;
118	    }
119	
120	    public static function isUndefinedColumnException(QueryException $exception): bool
121	    {
122	        $sqlState = $exception->errorInfo[0] ?? null;
123	
124	        return $sqlState === '42703';
125	    }
126	
127	    public function professional(): BelongsTo
128	    {
129	        return $this->belongsTo(Professional::class, 'professional_id');
130	    }
131	
132	    public function site(): BelongsTo
133	    {
134	        return $this->belongsTo(Site::class, 'site_id');
135	    }
136	
137	    public function block(): BelongsTo
138	    {
139	        $foreignKey = self::resolveBlockForeignKeyColumn();
140	
141	        if (! $foreignKey && array_key_exists('link_block_id', $this->attributes)) {
142	            $foreignKey = 'link_block_id';
143	        }
144	
145	        if (! $foreignKey && array_key_exists('block_id', $this->attributes)) {
146	            $foreignKey = 'block_id';
147	        }
148	
149	        return $this->belongsTo(Block::class, $foreignKey ?? 'link_block_id');
150	    }
151	}
