86	    public function click(ClickRequest $request): JsonResponse
87	    {
88	        $data = $request->validated();
89	
90	        // Resolve site by ID or subdomain
91	        $site = $this->resolveSiteFromData($data);
92	
93	        if (! $site) {
94	            // 422 when site_id was given but failed the subdomain cross-check (IDOR attempt).
95	            // 404 when only a subdomain was given and simply wasn't found.
96	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
97	
98	            return $this->error('Site not found', $statusCode);
99	        }
100	
101	        // 404 not 403: public endpoint — returning 403 would reveal the site exists but is unpublished
102	        if (! $site->is_published) {
103	            return $this->error('Site not found', 404);
104	        }
105	
106	        // Verify block exists and belongs to this site
107	        $block = Block::where('id', $data['block_id'])
108	            ->where('site_id', $site->id)
109	            ->first();
110	
111	        if (! $block) {
112	            return $this->error('Block not found or does not belong to this site', 404);
113	        }
114	
115	        $blockGroup = strtolower((string) $block->block_group);
116	        $blockType = strtolower((string) $block->block_type);
117	        $trackableSectionTypes = collect(config('sidest.section_block_types', [
118	            'gallery',
119	            'services',
120	            'shop',
121	            'booking',
122	        ]))
123	            ->filter(fn ($type) => is_string($type) && trim($type) !== '')
124	            ->map(fn (string $type) => strtolower(trim($type)))
125	            ->values()
126	            ->all();
127	        $isTrackableLink = $blockGroup === 'links' && $blockType === 'link';
128	        $isTrackableSection =
129	            $blockGroup === 'sections'
130	            && in_array($blockType, $trackableSectionTypes, true);
131	
132	        if (! $isTrackableLink && ! $isTrackableSection) {
133	            return $this->error('Block is not trackable for analytics', 422);
134	        }
135	
136	        // 404 not 403: state check on a public endpoint — 403 reveals the block exists but is disabled
137	        if (! $block->is_active) {
138	            return $this->error('Block not found', 404);
139	        }
140	
141	        $click = LinkClick::runForBlockForeignKey(
142	            function (string $blockColumn) use ($request, $data, $site, $block) {
143	                // Dedup: return existing click if same visitor/session hit this block within 3 seconds.
144	                $hasIdentifier = ! empty($data['visitor_id']) || ! empty($data['session_id']);
145	                if ($hasIdentifier) {
146	                    $duplicate = LinkClick::where($blockColumn, $block->id)
147	                        ->where(function ($q) use ($data) {
148	                            if (! empty($data['visitor_id'])) {
149	                                $q->orWhere('visitor_id', $data['visitor_id']);
150	                            }
151	                            if (! empty($data['session_id'])) {
152	                                $q->orWhere('session_id', $data['session_id']);
153	                            }
154	                        })
155	                        ->where('occurred_at', '>=', now()->subSeconds(3))
156	                        ->first();
157	
158	                    if ($duplicate) {
159	                        return $duplicate;
160	                    }
161	                }
162	
163	                $click = new LinkClick([
164	                    'occurred_at' => now(),
165	                    'session_id' => $data['session_id'] ?? null,
166	                    'visitor_id' => $data['visitor_id'] ?? null,
167	                    'ip_hash' => $this->hashIp($request->ip()),
168	                    'user_agent' => $request->userAgent(),
169	                    'referrer' => $data['referrer'] ?? $request->headers->get('referer'),
170	                    'utm_source' => $data['utm_source'] ?? null,
171	                    'utm_medium' => $data['utm_medium'] ?? null,
172	                    'utm_campaign' => $data['utm_campaign'] ?? null,
173	                ]);
174	                $click->professional_id = $site->professional_id;
175	                $click->site_id = $site->id;
176	                $click->setAttribute($blockColumn, $block->id);
177	                $click->save();
178	
179	                return $click;
180	            }
181	        );
182	
183	        if (! $click instanceof LinkClick) {
184	            return $this->error('Unable to record click due to schema mismatch', 500);
185	        }
186	
187	        RebuildSiteHourlyAggregatesJob::dispatch(
188	            (string) $site->professional_id,
189	            $click->occurred_at?->copy()->utc()->startOfHour()->toIso8601String() ?? now()->utc()->startOfHour()->toIso8601String()
190	        );
191	
192	        try {
193	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
194	        } catch (Throwable) {
195	        }
196	
197	        return $this->success([
198	            'message' => $isTrackableSection ? 'Section interaction recorded' : 'Click recorded',
199	            'click_id' => $click->id,
200	        ], 201);
201	    }
